1 | // Several Bob chats at once: one ViewState per agent, folded from the events that name it.
2 | // No DOM here, so it is testable. view.ts still folds a single agent.
3 | import type { AgentInfo, SseEvent, SseStateEvent } from "@lazycops/contracts";
4 | import type { ViewState } from "./view.js";
5 | import { currentCard, emptyView, fromSnapshot, reduce } from "./view.js";
6 | 
7 | /** Events that name no agent come from one chat without hooks, or from a server before agents. */
8 | export const SOLO = "solo";
9 | 
10 | export interface AgentView {
11 |   id: string;
12 |   /** 1, 2, 3…: the agent's call sign and colour. */
13 |   n: number;
14 |   view: ViewState;
15 | }
16 | 
17 | export interface SquadView {
18 |   connected: boolean;
19 |   agents: AgentView[];
20 | }
21 | 
22 | export const emptySquad = (): SquadView => ({ connected: false, agents: [] });
23 | 
24 | const agentOf = (event: SseEvent) => ("agent" in event && event.agent) || SOLO;
25 | const connected = (): ViewState => ({ ...emptyView(), connected: true });
26 | 
27 | /** Rebuilds every agent from the server's snapshot: the page keeps no state of its own. */
28 | function fromSquadSnapshot(snapshot: SseStateEvent): SquadView {
29 |   if (!snapshot.agents) {
30 |     const view = fromSnapshot(snapshot);
31 |     return { connected: true, agents: view.task !== null ? [{ id: SOLO, n: 1, view }] : [] };
32 |   }
33 |   const agents = snapshot.agents.map((info: AgentInfo) => {
34 |     const own = snapshot.history.filter((e) => agentOf(e) === info.id);
35 |     const view = own.reduce(reduce, connected());
36 |     return { id: info.id, n: info.n, view: { ...view, task: info.task, ended: !info.watching, hold: info.hold } };
37 |   });
38 |   return { connected: true, agents };
39 | }
40 | 
41 | export function reduceSquad(squad: SquadView, event: SseEvent): SquadView {
42 |   if (event.type === "state") return fromSquadSnapshot(event);
43 |   const id = agentOf(event);
44 |   let agents = squad.agents;
45 |   // A start while every agent has ended begins a fresh squad, as the server does.
46 |   if (event.type === "session" && event.on && agents.every((a) => a.view.ended)) agents = [];
47 |   const known = agents.find((a) => a.id === id);
48 |   const current = known ?? { id, n: agents.length + 1, view: connected() };
49 |   const next = { ...current, view: reduce(current.view, event) };
50 |   return { connected: true, agents: known ? agents.map((a) => (a === known ? next : a)) : [...agents, next] };
51 | }
52 | 
53 | export function disconnected(squad: SquadView): SquadView {
54 |   return { connected: false, agents: squad.agents.map((a) => ({ ...a, view: { ...a.view, connected: false } })) };
55 | }
56 | 
57 | /**
58 |  * The agent the page shows: the one picked; else the one whose card has waited longest, so a
59 |  * question is never hidden behind another agent; else the newest still watched; else the newest.
60 |  */
61 | export function focused(squad: SquadView, pick: string | null): AgentView | undefined {
62 |   const asking = squad.agents
63 |     .filter((a) => !a.view.ended && currentCard(a.view))
64 |     .sort((a, b) => Date.parse(currentCard(a.view)!.at) - Date.parse(currentCard(b.view)!.at))[0];
65 |   return squad.agents.find((a) => a.id === pick)
66 |     ?? asking
67 |     ?? [...squad.agents].reverse().find((a) => !a.view.ended)
68 |     ?? squad.agents.at(-1);
69 | }
70 | 
71 | /** The view of the agent in focus, or an empty one before any agent starts. */
72 | export function focusedView(squad: SquadView, pick: string | null): ViewState {
73 |   return focused(squad, pick)?.view ?? { ...emptyView(), connected: squad.connected };
74 | }
75 |

