1 | // How each agent looks: agent n wears the nth armour colour. Original pixel art; the names are LazyCop's own.
2 | import type { Palette } from "./map-art.js";
3 | import { SOLDIER, soldierPalette, spriteUrl } from "./map-art.js";
4 | import { asset, tinted } from "./map-assets.js";
5 | 
6 | /** Armour and leg colours, one pair per agent, repeating after six. */
7 | const ARMOUR: [string, string][] = [
8 |   ["#b8321e", "#7a2214"], ["#2c5bd0", "#1c3a88"], ["#2f9a3c", "#1d6326"],
9 |   ["#d49a1a", "#8a6310"], ["#8a3cc4", "#5a2388"], ["#d0602a", "#8a3c18"],
10 | ];
11 | 
12 | export const WEAPON = "DECLARE STEP";
13 | 
14 | const armour = (n: number) => ARMOUR[(Math.max(1, n) - 1) % ARMOUR.length]!;
15 | export const agentColor = (n: number) => armour(n)[0];
16 | export const agentPalette = (n: number): Palette => soldierPalette(...armour(n));
17 | export const callSign = (n: number) => `BOB-${n}`;
18 | 
19 | const cache = new Map<string, string>();
20 | const cached = (key: string, make: () => string) => cache.get(key) ?? (cache.set(key, make()), cache.get(key)!);
21 | 
22 | /** Painted art scales smoothly; the built-in sprites keep hard pixel edges. */
23 | export const imgClass = (name: "unit" | "portrait") => (asset(name) ? "art" : "pixel");
24 | 
25 | /** Full-body image as a URL: assets/unit.png in the agent's colour if present, else the built-in sprite. */
26 | export const unitSprite = (n: number) => asset("unit")
27 |   ? cached(`unit-${n}`, () => tinted("unit", agentColor(n))!.toDataURL())
28 |   : cached(`body-${n}`, () => spriteUrl(SOLDIER[0]!, agentPalette(n), 8));
29 | /** Head and shoulders, for portraits: assets/portrait.png if present, else the built-in sprite. */
30 | export const unitPortrait = (n: number) => asset("portrait")
31 |   ? asset("portrait")!.src
32 |   : cached(`head-${n}`, () => spriteUrl(SOLDIER[0]!.slice(0, 7), agentPalette(n), 6));
33 |

