1 | // The soldier's loadout on the unit profile: weapons (Bob's tools), skills and squadmates (subagents).
2 | import type { Loadout } from "./loadout.js";
3 | import { WEAPONS, lockedSkills } from "./loadout.js";
4 | import { esc } from "./page-state.js";
5 | 
6 | const LABEL = "font-family:var(--px);font-size:5px;color:var(--c-muted);margin:6px 0 4px;line-height:1.5";
7 | const LINE = "font-size:10px;line-height:1.5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap";
8 | 
9 | /** Bob's mode, as the soldier's class; Bob's hooks do not say which mode a task started in. */
10 | export const classOf = (l: Loadout) => (l.mode ? l.mode.toUpperCase() : "STARTING MODE");
11 | 
12 | function weapons(l: Loadout): string {
13 |   return WEAPONS.map((w) => {
14 |     const n = l.shots[w.cls];
15 |     return `<div class="loadout-slot" style="padding:4px;text-align:center;${n ? "" : "opacity:.4"}" title="${esc(`${w.name}: Bob ${w.what}`)}">
16 |       <span class="slot-icon" style="font-size:14px">${w.icon}</span>
17 |       <div class="slot-name" style="font-size:5px">${w.name}</div>
18 |       <div class="slot-name" style="font-size:7px;color:#fff;margin-top:2px">×${n}</div>
19 |     </div>`;
20 |   }).join("");
21 | }
22 | 
23 | function skills(l: Loadout): string {
24 |   const about = new Map(l.defined.map((s) => [s.name, s.description]));
25 |   const learned = l.learned.map((name) =>
26 |     `<div style="${LINE};color:var(--c-gold)" title="${esc(about.get(name) ?? "Bob's built-in skill")}">✦ ${esc(name)}</div>`);
27 |   const locked = lockedSkills(l).map((s) =>
28 |     `<div style="${LINE};color:#555" title="${esc(s.description)}">🔒 ${esc(s.name)}</div>`);
29 |   const list = [...learned, ...locked].join("");
30 |   return list || `<div style="${LINE};color:#555">No skills in .bob/skills</div>`;
31 | }
32 | 
33 | function squadmates(l: Loadout): string {
34 |   if (l.subagents.length === 0) return `<div style="${LINE};color:#555">None deployed</div>`;
35 |   const rows = l.subagents.map((s) => {
36 |     const status = s.running ? `<span style="color:var(--c-green)">RUNNING</span>`
37 |       : s.returned ? `<span style="color:var(--c-muted)">DONE</span>` : `<span style="color:var(--c-red2)">NO RESULT</span>`;
38 |     return `<div style="${LINE}" title="${esc(s.task)}">🪖 ${esc(s.preset)} · ${status} · ${s.calls} calls — ${esc(s.task)}</div>`;
39 |   });
40 |   const shared = l.sharedCalls
41 |     ? [`<div style="${LINE};color:var(--c-muted)">+${l.sharedCalls} calls by subagents running together</div>`]
42 |     : [];
43 |   return [...rows, ...shared].join("");
44 | }
45 | 
46 | export function renderLoadout(l: Loadout): string {
47 |   return `<div class="loadout" style="flex-direction:column;gap:0;overflow-y:auto;min-height:0">
48 |     <div style="${LABEL}">WEAPONS (BOB'S TOOLS):</div>
49 |     <div style="display:flex;gap:4px">${weapons(l)}</div>
50 |     <div style="${LABEL}">SKILLS:</div>
51 |     ${skills(l)}
52 |     <div style="${LABEL}">SQUADMATES (SUBAGENTS):</div>
53 |     ${squadmates(l)}
54 |   </div>`;
55 | }
56 |

Contents of file packages/page/src/view.ts:

1 | // What the page shows, folded from the server's event stream. No DOM here, so it is testable.
2 | import type { AnswerRecord, CardRecord, SseEvent, SseStateEvent } from "@lazycops/contracts";
3 | import type { Loadout } from "./loadout.js";
4 | import { emptyLoadout, foldLoadout } from "./loadout.js";
5 | 
6 | export interface CardView {
7 |   card: CardRecord;
8 |   /** When Bob stops waiting on this card, if it paused. */
9 |   waitUntil?: string;
10 |   answer?: AnswerRecord;
11 |   /** How many trail stops Bob had made when the card arrived; the card stands where he was. */
12 |   trailAt: number;
13 |   /** When the card arrived. */
14 |   at: string;
15 |   /** When the developer answered, to keep the latest exchange in view. */
16 |   answeredAt?: string;
17 |   /** Bob's replies and the developer's follow-ups on this card, in order. */
18 |   thread: { from: "bob" | "you"; text: string }[];
19 | }
20 | 
21 | export interface FeedItem {
22 |   at: string;
23 |   kind: "step" | "read" | "edit" | "reply" | "you" | "hold" | "session" | "doc";
24 |   text: string;
25 | }
26 | 
27 | /** One place Bob went: a file he read, searched or edited, or a shell command (no path). */
28 | export interface TrailStop {
29 |   at: string;
30 |   kind: "read" | "search" | "edit" | "command";
31 |   /** Relative to the watched repo when Bob gave an absolute path; null for a command. */
32 |   path: string | null;
33 | }
34 | 
35 | export interface ViewState {
36 |   connected: boolean;
37 |   task: string | null;
38 |   /** true once the watched task has ended; the page then shows the wrap-up. */
39 |   ended: boolean;
40 |   hold: boolean;
41 |   /** The card Bob is held on, when an important decision started the hold. */
42 |   holdCard?: string;
43 |   /** Set while Bob waits in check_in for the developer's answer. */
44 |   waiting: { until?: string; card?: string } | null;
45 |   cards: CardView[];
46 |   feed: FeedItem[];
47 |   filesRead: string[];
48 |   filesEdited: string[];
49 |   trail: TrailStop[];
50 |   /** Bob's tools, skills, subagents and mode, as the soldier's loadout. */
51 |   loadout: Loadout;
52 | }
53 | 
54 | export const EDIT_TOOLS = ["apply_diff", "write_file", "search_and_replace", "insert_content"];
55 | 
56 | export const READ_TOOLS = ["read_file", "list_code_definition_names"];
57 | export const SEARCH_TOOLS = ["search_files", "list_files", "codebase_search"];
58 | export const COMMAND_TOOLS = ["execute_command"];
59 | 
60 | function toolKind(tool: string): TrailStop["kind"] | null {
61 |   if (EDIT_TOOLS.includes(tool)) return "edit";
62 |   if (READ_TOOLS.includes(tool)) return "read";
63 |   if (SEARCH_TOOLS.includes(tool)) return "search";
64 |   return COMMAND_TOOLS.includes(tool) ? "command" : null;
65 | }
66 | 
67 | function relative(path: string, cwd: string): string {
68 |   const root = cwd.replace(/\/+$/, "");
69 |   return root && path.startsWith(`${root}/`) ? path.slice(root.length + 1) : path;
70 | }
71 | 
72 | export const emptyView = (): ViewState => ({
73 |   connected: false, task: null, ended: false, hold: false, waiting: null, cards: [], feed: [], filesRead: [], filesEdited: [], trail: [], loadout: emptyLoadout(),
74 | });
75 | 
76 | /** Rebuilds the whole view from the server's snapshot: the page keeps no state of its own. */
77 | export function fromSnapshot(snapshot: SseStateEvent): ViewState {
78 |   let view: ViewState = { ...emptyView(), connected: true };
79 |   for (const event of snapshot.history) view = reduce(view, event);
80 |   return { ...view, task: snapshot.session?.task ?? view.task, ended: snapshot.session === null && view.task !== null, hold: snapshot.hold };
81 | }
82 | 
83 | const addOnce = (list: string[], item: string) => (list.includes(item) ? list : [...list, item]);
84 | 
85 | function pathOf(input: unknown): string | undefined {
86 |   const p = input && typeof input === "object" ? (input as Record<string, unknown>)["path"] : undefined;
87 |   return typeof p === "string" ? p : undefined;
88 | }
89 | 
90 | export function reduce(view: ViewState, event: SseEvent): ViewState {
91 |   const feed = (kind: FeedItem["kind"], text: string): FeedItem[] => [...view.feed, { at: event.at, kind, text }];
92 |   switch (event.type) {
93 |     case "state":
94 |       return fromSnapshot(event);
95 |     case "session":
96 |       return event.on
97 |         ? { ...emptyView(), connected: true, task: event.task ?? "", loadout: emptyLoadout(event.skills), feed: [{ at: event.at, kind: "session", text: "LazyCop started watching" }] }
98 |         : { ...view, ended: true, hold: false, waiting: null, feed: feed("session", "LazyCop stopped watching") };
99 |     case "hold":
100 |       return { ...view, hold: event.on, holdCard: event.on ? event.card : undefined, feed: feed("hold", event.on ? "Bob is on hold" : `Hold released (${event.reason})`) };
101 |     case "doc":
102 |       return { ...view, feed: feed("doc", `LazyCop knows ${event.path} (${event.source === "named" ? "you named it" : "Bob read it"})`) };
103 |     case "waiting":
104 |       return { ...view, waiting: event.on ? { until: event.until, card: event.card } : null };
105 |     case "card": {
106 |       // A card can arrive twice: the writer's alternative readings update it in place.
107 |       const known = view.cards.find((c) => c.card.id === event.card.id);
108 |       return known
109 |         ? { ...view, cards: view.cards.map((c) => (c === known ? { ...c, card: event.card, waitUntil: event.waitUntil ?? c.waitUntil } : c)) }
110 |         : { ...view, cards: [...view.cards, { card: event.card, waitUntil: event.waitUntil, thread: [], trailAt: view.trail.length, at: event.at }] };
111 |     }
112 |     case "answer":
113 |       return { ...view, cards: view.cards.map((c) => (c.card.id === event.answer.card ? { ...c, answer: event.answer, answeredAt: event.at } : c)) };
114 |     case "reply": {
115 |       const target = event.card ?? [...view.cards].reverse().find((c) => c.answer)?.card.id;
116 |       return {
117 |         ...view,
118 |         cards: view.cards.map((c) => (c.card.id === target ? { ...c, thread: [...c.thread, { from: "bob" as const, text: event.text }] } : c)),
119 |         feed: feed("reply", event.text),
120 |       };
121 |     }
122 |     case "queued":
123 |       if (event.fromAnswer) return view;
124 |       if (event.card) {
125 |         return { ...view, cards: view.cards.map((c) => (c.card.id === event.card ? { ...c, thread: [...c.thread, { from: "you" as const, text: event.text }] } : c)) };
126 |       }
127 |       return { ...view, feed: feed("you", event.text) };
128 |     case "mcp":
129 |       return event.tool === "declare_step" ? { ...view, feed: feed("step", String(event.args["intent"] ?? "")) } : view;
130 |     case "hook": {
131 |       const p = event.payload;
132 |       const loadout = foldLoadout(view.loadout, p);
133 |       if (loadout !== view.loadout) view = { ...view, loadout };
134 |       if (p.hook_event_name !== "PostToolUse" || p.tool_name.startsWith("mcp__lazycop__")) return view;
135 |       const kind = toolKind(p.tool_name);
136 |       const path = pathOf(p.tool_input);
137 |       if (!kind || (kind !== "command" && !path)) return view;
138 |       const trail = [...view.trail, { at: event.at, kind, path: path ? relative(path, p.cwd) : null }];
139 |       if (kind === "edit") return { ...view, trail, filesEdited: addOnce(view.filesEdited, path!), feed: feed("edit", path!) };
140 |       if (p.tool_name === "read_file") return { ...view, trail, filesRead: addOnce(view.filesRead, path!), feed: feed("read", path!) };
141 |       return { ...view, trail };
142 |     }
143 |     default:
144 |       return view;
145 |   }
146 | }
147 | 
148 | /** What Bob is waiting on the developer for: his last message on the card, if he asked on one. */
149 | export function waitingQuestion(view: ViewState): { card?: string; text?: string } | null {
150 |   if (!view.waiting) return null;
151 |   const card = view.cards.find((c) => c.card.id === view.waiting!.card);
152 |   const last = card?.thread.at(-1);
153 |   return { card: card?.card.id, text: last?.from === "bob" ? last.text : undefined };
154 | }
155 | 
156 | /** Where a card came from, as the page labels it. */
157 | export function sourceLabel(card: CardRecord): string {
158 |   return { declare_step: "Before an edit", diff: "After an edit", end_session: "Final review", confirm: "Checking your correction", spec: "Spec check" }[card.source] ?? "Question";
159 | }
160 | 
161 | /** Answered cards, latest answer first: the first stays open under the current card, the rest fold away. */
162 | export function answeredCards(view: ViewState): CardView[] {
163 |   return view.cards.filter((c) => c.answer).sort((a, b) => (b.answeredAt ?? "").localeCompare(a.answeredAt ?? ""));
164 | }
165 | 
166 | /** For a confirmation card: what the developer had said on the card it confirms. */
167 | export function correctionBeingConfirmed(view: ViewState, c: CardView): string | undefined {
168 |   const original = c.card.confirms ? view.cards.find((o) => o.card.id === c.card.confirms) : undefined;
169 |   return original?.answer?.text;
170 | }
171 | 
172 | /** The card the developer should look at now: the oldest unanswered one. */
173 | export function currentCard(view: ViewState): CardView | undefined {
174 |   return view.cards.find((c) => !c.answer);
175 | }
176 | 
177 | export function summary(view: ViewState) {
178 |   const answered = view.cards.filter((c) => c.answer);
179 |   return {
180 |     cards: view.cards.length,
181 |     agreed: answered.filter((c) => c.answer!.pick === "bob").length,
182 |     corrected: answered.filter((c) => c.answer!.pick !== "bob" && c.answer!.pick !== "ask_why").length,
183 |     askedWhy: answered.filter((c) => c.answer!.pick === "ask_why").length,
184 |     unanswered: view.cards.length - answered.length,
185 |     filesEdited: view.filesEdited,
186 |   };
187 | }
188 | 
189 | /** Health lost each time the developer corrects one of Bob's assumptions. */
190 | export const HIT = 20;
191 | 
192 | /** Bob's health, 0–100: agreeing or asking why costs nothing, a correction costs HIT. */
193 | export function health(view: ViewState): number {
194 |   return Math.max(0, 100 - HIT * summary(view).corrected);
195 | }
196 |

Contents of file packages/page/src/loadout.ts:

1 | // A soldier's loadout, folded from Bob's own hook events: tools are weapons, skills are learned,
2 | // subagents are the soldier's squadmates. No DOM here, so it is testable. Every number is a count
3 | // of real hook events; nothing is estimated.
4 | import type { HookPayload, SkillInfo } from "@lazycops/contracts";
5 | import { COMMAND_TOOLS, EDIT_TOOLS, READ_TOOLS, SEARCH_TOOLS } from "./view.js";
6 | 
7 | export type WeaponClass = "recon" | "search" | "edit" | "command" | "radio";
8 | 
9 | export interface Weapon {
10 |   cls: WeaponClass;
11 |   name: string;
12 |   icon: string;
13 |   /** What the weapon is, in Bob's terms. */
14 |   what: string;
15 | }
16 | 
17 | export const WEAPONS: Weapon[] = [
18 |   { cls: "recon", name: "SCOPE", icon: "🔭", what: "reads files" },
19 |   { cls: "search", name: "RADAR", icon: "📡", what: "searches and lists files" },
20 |   { cls: "edit", name: "RIFLE", icon: "🔫", what: "edits files" },
21 |   { cls: "command", name: "EXPLOSIVES", icon: "💣", what: "runs commands" },
22 |   { cls: "radio", name: "RADIO", icon: "📻", what: "talks to you through LazyCop" },
23 | ];
24 | 
25 | /** One Bob subagent, from its spawn_subagent call. */
26 | export interface SubagentView {
27 |   /** The spawn_subagent call's tool_use_id. */
28 |   id: string;
29 |   /** Bob's preset, e.g. "explore"; "general" when Bob named none. */
30 |   preset: string;
31 |   task: string;
32 |   running: boolean;
33 |   /** false when it ended without a result: Bob fires no PostToolUse for a failed call. */
34 |   returned: boolean;
35 |   /** Tool calls made while it was the only subagent running. */
36 |   calls: number;
37 | }
38 | 
39 | export interface Loadout {
40 |   /** Tool calls the soldier made itself, by weapon; calls made while a subagent ran are not counted here. */
41 |   shots: Record<WeaponClass, number>;
42 |   /** Skills defined in the watched repo, from the session start. */
43 |   defined: SkillInfo[];
44 |   /** Skills Bob loaded with use_skill since the last compaction, in order. */
45 |   learned: string[];
46 |   /** The mode Bob last switched to; null until Bob switches. */
47 |   mode: string | null;
48 |   subagents: SubagentView[];
49 |   /** Tool calls made while several subagents ran at once: Bob does not say which one made them. */
50 |   sharedCalls: number;
51 | }
52 | 
53 | export const emptyLoadout = (defined: SkillInfo[] = []): Loadout => ({
54 |   shots: { recon: 0, search: 0, edit: 0, command: 0, radio: 0 },
55 |   defined, learned: [], mode: null, subagents: [], sharedCalls: 0,
56 | });
57 | 
58 | const OWN_TOOL = "mcp__lazycop__";
59 | 
60 | function weaponOf(tool: string): WeaponClass | null {
61 |   if (tool.startsWith(OWN_TOOL)) return "radio";
62 |   if (EDIT_TOOLS.includes(tool)) return "edit";
63 |   if (READ_TOOLS.includes(tool)) return "recon";
64 |   if (SEARCH_TOOLS.includes(tool) || tool === "grep") return "search";
65 |   return COMMAND_TOOLS.includes(tool) ? "command" : null;
66 | }
67 | 
68 | function arg(input: unknown, key: string): string | undefined {
69 |   const v = input && typeof input === "object" ? (input as Record<string, unknown>)[key] : undefined;
70 |   return typeof v === "string" && v.trim() !== "" ? v.trim() : undefined;
71 | }
72 | 
73 | /** Credits one finished tool call: to the soldier, to the one running subagent, or to the running group. */
74 | function credit(l: Loadout, cls: WeaponClass): Loadout {
75 |   const running = l.subagents.filter((s) => s.running);
76 |   if (running.length === 0) return { ...l, shots: { ...l.shots, [cls]: l.shots[cls] + 1 } };
77 |   if (running.length > 1) return { ...l, sharedCalls: l.sharedCalls + 1 };
78 |   return { ...l, subagents: l.subagents.map((s) => (s === running[0] ? { ...s, calls: s.calls + 1 } : s)) };
79 | }
80 | 
81 | /** Folds one hook event into the loadout; returns the same object when nothing changed. */
82 | export function foldLoadout(l: Loadout, p: HookPayload): Loadout {
83 |   if (p.hook_event_name === "PostCompact") return l.learned.length ? { ...l, learned: [] } : l;
84 |   if (p.hook_event_name === "PreToolUse" && p.tool_name === "spawn_subagent") {
85 |     const sub = { id: p.tool_use_id, preset: arg(p.tool_input, "name") ?? "general", task: arg(p.tool_input, "description") ?? "", running: true, returned: false, calls: 0 };
86 |     return { ...l, subagents: [...l.subagents, sub] };
87 |   }
88 |   // The chat's turn is over, so every subagent has ended; one still open failed.
89 |   if (p.hook_event_name === "Stop") {
90 |     return l.subagents.some((s) => s.running) ? { ...l, subagents: l.subagents.map((s) => ({ ...s, running: false })) } : l;
91 |   }
92 |   // PostToolUse fires only for a call that succeeded (Bob 2.2.0).
93 |   if (p.hook_event_name !== "PostToolUse") return l;
94 |   switch (p.tool_name) {
95 |     case "spawn_subagent":
96 |       return { ...l, subagents: l.subagents.map((s) => (s.id === p.tool_use_id ? { ...s, running: false, returned: true } : s)) };
97 |     case "use_skill": {
98 |       const skill = arg(p.tool_input, "skill_name");
99 |       return skill && !l.learned.includes(skill) ? { ...l, learned: [...l.learned, skill] } : l;
100 |     }
101 |     case "switch_mode": {
102 |       const mode = arg(p.tool_input, "mode_id");
103 |       return mode ? { ...l, mode } : l;
104 |     }
105 |   }
106 |   const cls = weaponOf(p.tool_name);
107 |   return cls ? credit(l, cls) : l;
108 | }
109 | 
110 | /** Skills Bob has not loaded since the last compaction, among those the repo defines. */
111 | export const lockedSkills = (l: Loadout): SkillInfo[] => l.defined.filter((s) => !l.learned.includes(s.name));
