15 | const root = document.getElementById("app")!;
16 | 
17 | function render(): void {
18 |   // Preserve input values and focus across renders
19 |   const kept = new Map<string, string | boolean>();
20 |   root.querySelectorAll<HTMLInputElement>("[data-keep]").forEach((el) =>
21 |     kept.set(el.dataset.keep!, el.type === "checkbox" ? el.checked : el.value)
22 |   );
23 |   const focused = (document.activeElement as HTMLElement | null)?.dataset?.keep;
24 | 
25 |   // Auto-enter the mission when a task starts, and stay for its wrap-up once it ends
26 |   // until the developer goes back to the briefing.
27 |   const { view } = ui;
28 |   if (!view.ended) ui.leftEnded = false;
29 |   if (view.task !== null && !ui.leftEnded) ui.inMission = true;
30 |   if (view.task === null) ui.inMission = false;
31 | 
32 |   const noticeHtml = ui.notice ? `<p class="notice-bar">${esc(ui.notice)}</p>` : "";
33 |   root.innerHTML = noticeHtml + (ui.inMission ? renderMissionScreen() : renderBriefingScreen()) + renderPanels();
34 |   updateMap(ui.squad, focusedAgent()?.id);
35 |   attachMap(root.querySelector<HTMLElement>(".map-host"));
36 | 
37 |   root.querySelectorAll<HTMLInputElement>("[data-keep]").forEach((el) => {
38 |     const v = kept.get(el.dataset.keep!);
39 |     if (typeof v === "boolean") el.checked = v;
40 |     else if (typeof v === "string") el.value = v;
41 |   });
42 |   if (focused) root.querySelector<HTMLElement>(`[data-keep="${focused}"]`)?.focus();
43 | }
44 | onRender(render);
