46 | /** Shows another agent; the screens, the HUD's hold and new messages then act on it. */
47 | function focusOn(agent: string): void {
48 |   ui.focus = agent;
49 |   refocus();
50 |   render();
51 | }
52 | onPickAgent(focusOn);
53 | onAssetsChanged(render);
