55 | // ── Event delegation ─────────────────────────────────────────
56 | function answer(card: string, pick: string, text?: string): void {
57 |   void post("/answer", { card, pick, ...(text ? { text } : {}) });
58 | }
59 | 
60 | root.addEventListener("click", (e) => {
61 |   const el = (e.target as HTMLElement).closest<HTMLElement>("button, [data-enter-mission], [data-to-briefing]");
62 |   if (!el) return;
63 | 
64 |   if (el.dataset.mute !== undefined)         { toggleMute(); render(); return; }
65 |   if (el.dataset.hold !== undefined)         { void post("/hold", { on: !ui.view.hold, agent: focusedAgent()?.id }); return; }
66 |   if (el.dataset.logToggle !== undefined)    { ui.logOpen = !ui.logOpen; render(); return; }
67 |   if (el.dataset.histToggle !== undefined)   { ui.histOpen = !ui.histOpen; render(); return; }
68 |   if (el.dataset.enterMission !== undefined) { ui.inMission = true; render(); return; }
69 |   if (el.dataset.toBriefing !== undefined)   { ui.inMission = false; ui.leftEnded = ui.view.ended; render(); return; }
70 |   if (el.dataset.agent !== undefined)        { focusOn(el.dataset.agent); return; }
71 | 
72 |   const { card, pick, text } = el.dataset;
73 |   if (!card || !pick) return;
74 |   if (pick === "other") {
75 |     const form = root.querySelector<HTMLFormElement>(`[data-other="${card}"]`)!;
76 |     form.hidden = false;
77 |     form.querySelector("input")!.focus();
78 |     return;
79 |   }
80 |   if (pick === "bob") sfxAgree();
81 |   else if (pick !== "ask_why") sfxChallenge();
82 |   answer(card, pick, pick === "ask_why" ? undefined : text);
83 | });
84 | 
85 | root.addEventListener("submit", (e) => {
86 |   e.preventDefault();
87 |   const form = e.target as HTMLFormElement;
88 |   const input = form.querySelector<HTMLInputElement>('input[name="text"]')!;
89 |   const text = input.value.trim();
90 |   if (!text) return;
91 |   input.value = "";
92 |   if (form.dataset.other)   { answer(form.dataset.other, "other", text); return; }
93 |   if (form.dataset.thread)  { void post("/queue", { text, card: form.dataset.thread }); return; }
94 |   if (form.dataset.compose !== undefined) {
95 |     const urgent = form.querySelector<HTMLInputElement>('input[name="urgent"]')?.checked ?? false;
96 |     void post("/queue", { text, channel: urgent ? "block" : "context", agent: focusedAgent()?.id });
97 |   }
98 | });
99 | 
100 | // Keyboard: 1/2/3 pick battle options
101 | document.addEventListener("keydown", (e) => {
102 |   if ((e.target as HTMLElement).tagName === "INPUT") return;
103 |   const n = Number(e.key);
104 |   if (ui.view.ended || !currentCard(ui.view) || !Number.isInteger(n) || n < 1) return;
105 |   root.querySelectorAll<HTMLButtonElement>("#battle-overlay .option")[n - 1]?.click();
106 | });
107 | 
108 | // Live countdown tick (no full re-render)
109 | setInterval(() => {
110 |   const now = currentCard(ui.view);
111 |   const cdWrap = now && root.querySelector(`[data-countdown="${now.card.id}"] .cd-wrap`);
112 |   if (cdWrap) cdWrap.innerHTML = countdownHtml(now, "battle-cd");
113 |   const left = root.querySelector("[data-left]");
114 |   if (left) left.textContent = `${secondsLeft(ui.view.waiting?.until)}s`;
115 | }, 1000);
116 | 
117 | // SSE stream
118 | const stream = new EventSource("/stream");
119 | stream.onmessage = (e) => {
120 |   const prevView = focusedView(ui.squad, ui.focus);
121 |   try { ui.squad = reduceSquad(ui.squad, JSON.parse(e.data) as SseEvent); }
122 |   catch { ui.notice = "Got an event LazyCop's page could not read"; }
123 |   refocus();
124 |   const nextView = ui.view;
125 |   if (nextView.cards.length > prevView.cards.length) sfxQuestion();
126 |   const prevEdits = prevView.trail.filter((t) => t.kind === "edit").length;
127 |   const nextEdits = nextView.trail.filter((t) => t.kind === "edit").length;
128 |   if (nextEdits > prevEdits) sfxEdit();
129 |   if (nextView.ended && !prevView.ended) sfxMissionClear();
130 |   render();
131 | };
132 | stream.onerror = () => { ui.squad = disconnected(ui.squad); refocus(); render(); };
133 | render();
