7 | export const START_TOOL = "mcp__lazycop__start_session";
8 | 
9 | /**
10 |  * Called from the PreToolUse hook of start_session, the only place Bob's
11 |  * session_id is visible. The latest invocation wins: a different task that
12 |  * was still being watched is ended first.
13 |  */
14 | export function bindSession(store: StoreState, id: string, cwd: string): void {
15 |   if (store.session?.id === id) return;
16 |   if (store.session) endSession(store);
17 |   store.session = { id, task: "", cwd };
18 |   setRecordDir(join(cwd, ".lazycop"));
19 | }
20 | 
21 | /** Called from the start_session MCP call. Without a hook binding, cards still work but hooks stay dormant. */
22 | export function startSession(store: StoreState, task: string): void {
23 |   store.history = [];
24 |   if (store.session) store.session.task = task;
25 |   else store.session = { id: null, task };
26 |   const { id } = store.session;
27 |   appendRecord({ kind: "session", ts: new Date().toISOString(), on: true, ...(id ? { id } : {}), task });
28 | }
29 | 
30 | export function endSession(store: StoreState): void {
31 |   if (!store.session) return;
32 |   const { id, task } = store.session;
33 |   appendRecord({ kind: "session", ts: new Date().toISOString(), on: false, ...(id ? { id } : {}), task });
34 |   cancelAllCards();
35 |   clearSession(store);
36 |   setRecordDir(null);
37 | }
