10 | export interface StoreState {
11 |   /** null while LazyCop is dormant. */
12 |   session: Session | null;
13 |   hold: boolean;
14 |   holdPolls: number;
15 |   /** The card whose important decision started the hold; answering it ends the hold. */
16 |   holdCard?: string;
17 |   seq: number;
18 |   pending: PendingMessage[];
19 |   /** Active cards indexed by id, so answers can find their card. */
20 |   cards: Map<string, CardRecord>;
