28 |   lastIntent?: string;
29 |   /** A card whose correction Bob has received; his next assumption card confirms it. */
30 |   confirmFor?: string;
31 |   /** The task's documents by workspace path, for the knowledge agent. */
32 |   docs: Map<string, string>;
33 |   waiters: Set<() => void>;
