50 | /** True when a hook payload belongs to the task LazyCop is watching. */
51 | export function isWatched(store: StoreState, sessionId: string): boolean {
52 |   return store.session !== null && store.session.id === sessionId;
53 | }
54 | 
55 | /** Drops everything tied to the current session and releases anything waiting on it. */
56 | export function clearSession(store: StoreState): void {
57 |   store.session = null;
58 |   store.hold = false;
59 |   store.holdPolls = 0;
60 |   store.holdCard = undefined;
61 |   store.pending = [];
62 |   store.cards.clear();
63 |   store.lastMessageCard = undefined;
64 |   store.lastReplyCard = undefined;
65 |   store.confirmFor = undefined;
66 |   store.docs.clear();
67 |   wake(store);
