70 | export function wake(store: StoreState): void {
71 |   for (const done of store.waiters) done();
72 |   store.waiters.clear();
73 | }
74 | 
75 | export function setHold(store: StoreState, on: boolean): void {
76 |   store.hold = on;
77 |   if (on) store.holdPolls = 0;
78 |   else store.holdCard = undefined;
79 |   wake(store);
80 | }
