82 | export function takePending(
83 |   store: StoreState,
84 |   channel: "block" | "context",
85 | ): PendingMessage | null {
86 |   const i = store.pending.findIndex((m) => m.channel === channel);
87 |   if (i === -1) return null;
88 |   const [msg] = store.pending.splice(i, 1);
89 |   return msg;
