92 | export function waitForDeveloper(store: StoreState, ms: number): Promise<void> {
93 |   return new Promise((resolve) => {
94 |     const done = () => { clearTimeout(timer); resolve(); };
95 |     const timer = setTimeout(() => { store.waiters.delete(done); resolve(); }, ms);
96 |     store.waiters.add(done);
97 |   });
