97 | export function createServer(): http.Server {
98 |   return http.createServer(async (req, res) => {
99 |     const url = new URL(req.url ?? "/", "http://localhost");
100 | 
101 |     if (req.method === "GET" && (url.pathname === "/" || /^\/[a-z-]+\.js$/.test(url.pathname))) {
102 |       return servePage(res, url.pathname);
103 |     }
104 |     // Only kebab-case .png files directly in assets/: the pattern leaves no room for another path.
105 |     if (req.method === "GET" && /^\/assets\/[a-z-]+\.png$/.test(url.pathname)) {
106 |       return serveAsset(res, url.pathname);
107 |     }
108 | 
109 |     if (req.method === "GET" && url.pathname === "/stream") {
110 |       res.writeHead(200, {
111 |         "content-type": "text/event-stream",
112 |         "cache-control": "no-cache",
113 |         connection: "keep-alive",
114 |       });
115 |       const current = latest(squad);
116 |       const snapshot: SseStateEvent = {
117 |         type: "state",
118 |         at: new Date().toISOString(),
119 |         session: current ? { task: current.task } : null,
120 |         hold: watching(squad).some((a) => a.store.hold),
121 |         agents: agentsInfo(squad),
122 |         pending: watching(squad).flatMap((a) => a.store.pending),
123 |         history: [...squad.history],
124 |       };
125 |       res.write(`data: ${JSON.stringify(snapshot)}\n\n`);
126 |       clients.add(res);
127 |       req.on("close", () => clients.delete(res));
128 |       return;
129 |     }
130 | 
131 |     if (req.method !== "POST") return json(res, { error: "not found" }, 404);
132 | 
133 |     const body = await readBody(req);
134 |     if (body === null) return json(res, { error: "invalid json" }, 400);
135 | 
136 |     switch (url.pathname) {
137 |       case "/hook": {
138 |         const payload = body as HookPayload;
139 |         const { agent, result } = routeHook(squad, payload);
140 |         if (agent && isWatching(agent) && shownOnPage(payload)) {
141 |           const send = tagged(push, agent);
142 |           send({ type: "hook", seq: ++squad.seq, payload });
143 |           void withRecords(agent, () => reviewEdit(agent.store, payload, send));
144 |           keepDocBobRead(agent, payload, send);
145 |         }
146 |         return json(res, result);
147 |       }
148 |       case "/mcp": {
149 |         const { tool, args } = body as { tool: string; args: Record<string, unknown> };
150 |         const text = await runMcp(squad, tool, args ?? {}, push);
151 |         if (tool === "start_session") openPage();
152 |         return json(res, { text });
153 |       }
154 |       case "/queue":
155 |       case "/hold":
156 |       case "/answer": {
157 |         const [status, reply] = onDeveloper(squad, url.pathname, body, push);
158 |         return json(res, reply, status);
159 |       }
160 |       default:
161 |         return json(res, { error: "not found" }, 404);
162 |     }
163 |   });
164 | }
