1 | // Several Bob chats at once: each chat that runs /lazycop is its own agent with its own store.
2 | // Hooks name their chat (session_id); MCP calls do not, so each one is matched to the
3 | // PreToolUse hook that Bob fired for it just before.
4 | import { join } from "node:path";
5 | import type { AgentInfo, HookPayload, SseEvent, SseEventInput } from "@lazycops/contracts";
6 | import type { StoreState } from "./store.js";
7 | import { createStore } from "./store.js";
8 | import type { HookResult } from "./hook.js";
9 | import { onHook } from "./hook.js";
10 | import type { Push } from "./mcp.js";
11 | import { onMcp } from "./mcp.js";
12 | import { START_TOOL } from "./session.js";
13 | import { withRecordDir } from "./logger.js";
14 | 
15 | /** The agent of a chat whose hooks are not installed: its MCP calls cannot be told apart. */
16 | export const SOLO = "solo";
17 | const OWN_TOOL = "mcp__lazycop__";
18 | /** A PreToolUse hook not followed by its MCP call within this long is forgotten. */
19 | const EXPECT_MS = 60_000;
20 | 
21 | export interface Agent {
22 |   id: string;
23 |   n: number;
24 |   store: StoreState;
25 |   /** Kept after the task ends, so the page can still name it. */
26 |   task: string;
27 |   lastActive: number;
28 | }
29 | 
30 | export interface Squad {
31 |   agents: Map<string, Agent>;
32 |   /** Own-tool PreToolUse hooks waiting for their MCP call, oldest first. */
33 |   expected: { tool: string; key: string; agent: Agent; at: number }[];
34 |   /** Every event pushed since LazyCop last went dormant; the page rebuilds from it. */
35 |   history: SseEvent[];
36 |   seq: number;
37 | }
38 | 
39 | export const createSquad = (): Squad => ({ agents: new Map(), expected: [], history: [], seq: 0 });
40 | 
41 | /**
42 |  * Whether the page sees a hook event. It only uses what happened, so tools show once, after they
43 |  * run; a subagent shows from its start too, so the page can tell its calls from its parent's.
44 |  */
45 | export const shownOnPage = (p: HookPayload) => p.hook_event_name !== "PreToolUse" || p.tool_name === "spawn_subagent";
46 | 
47 | export const isWatching = (agent: Agent) => agent.store.session !== null;
48 | export const watching = (squad: Squad) => [...squad.agents.values()].filter(isWatching);
49 | 
50 | /** The watched agent that acted last: where a message without an agent or card goes. */
51 | export const latest = (squad: Squad): Agent | undefined =>
52 |   watching(squad).sort((a, b) => b.lastActive - a.lastActive)[0];
53 | 
54 | export const agentOfCard = (squad: Squad, card: string): Agent | undefined =>
55 |   [...squad.agents.values()].find((a) => a.store.cards.has(card));
56 | 
57 | /** The same arguments give the same key, whatever order their fields came in. */
58 | function argsKey(value: unknown): string {
59 |   if (Array.isArray(value)) return `[${value.map(argsKey).join(",")}]`;
60 |   if (value && typeof value === "object") {
61 |     const o = value as Record<string, unknown>;
62 |     return `{${Object.keys(o).sort().map((k) => `${JSON.stringify(k)}:${argsKey(o[k])}`).join(",")}}`;
63 |   }
64 |   return JSON.stringify(value) ?? "null";
65 | }
66 | 
67 | /** The chat's agent, joining it to the squad if new. A start while nothing is watched begins a fresh page. */
68 | function joinAgent(squad: Squad, id: string): Agent {
69 |   if (watching(squad).length === 0) {
70 |     squad.agents.clear();
71 |     squad.history = [];
72 |     squad.expected = [];
73 |   }
74 |   let agent = squad.agents.get(id);
75 |   if (!agent) {
76 |     agent = { id, n: squad.agents.size + 1, store: createStore(), task: "", lastActive: Date.now() };
77 |     squad.agents.set(id, agent);
78 |   }
79 |   return agent;
80 | }
81 | 
82 | /** Runs one agent's work with its records going to its own workspace. */
83 | export function withRecords<T>(agent: Agent, fn: () => T): T {
84 |   const cwd = agent.store.session?.cwd;
85 |   return withRecordDir(cwd ? join(cwd, ".lazycop") : null, fn);
86 | }
87 | 
88 | /** Stamps every event an agent's work pushes with that agent. */
89 | export const tagged = (push: Push, agent: Agent): Push => (event: SseEventInput) =>
90 |   push(event.type === "state" ? event : { ...event, agent: agent.id });
91 | 
92 | export function routeHook(squad: Squad, payload: HookPayload): { agent?: Agent; result: HookResult } {
93 |   const pre = payload.hook_event_name === "PreToolUse" ? payload : null;
94 |   const agent = pre?.tool_name === START_TOOL ? joinAgent(squad, payload.session_id) : squad.agents.get(payload.session_id);
95 |   // Invariant 7: dormant for every chat LazyCop was not invoked in
96 |   if (!agent || (!isWatching(agent) && pre?.tool_name !== START_TOOL)) return { result: {} };
97 |   agent.lastActive = Date.now();
98 |   if (pre?.tool_name.startsWith(OWN_TOOL)) {
99 |     squad.expected.push({ tool: pre.tool_name.slice(OWN_TOOL.length), key: argsKey(pre.tool_input), agent, at: Date.now() });
100 |   }
101 |   return { agent, result: withRecords(agent, () => onHook(agent.store, payload)) };
102 | }
103 | 
104 | /** The agent an MCP call came from: the chat whose hook announced it, else the best guess. */
105 | export function routeMcp(squad: Squad, tool: string, args: unknown): Agent | undefined {
106 |   squad.expected = squad.expected.filter((e) => Date.now() - e.at < EXPECT_MS);
107 |   const key = argsKey(args);
108 |   // Exact match first; then the oldest hook for the same tool, in case Bob reshaped the arguments.
109 |   const i = [squad.expected.findIndex((e) => e.tool === tool && e.key === key), squad.expected.findIndex((e) => e.tool === tool)]
110 |     .find((j) => j >= 0);
111 |   if (i !== undefined) return squad.expected.splice(i, 1)[0]!.agent;
112 |   // No hook announced it: hooks are not installed in that chat.
113 |   return tool === "start_session" ? joinAgent(squad, SOLO) : latest(squad);
114 | }
115 | 
116 | export async function runMcp(squad: Squad, tool: string, args: Record<string, unknown>, push: Push): Promise<string> {
117 |   const agent = routeMcp(squad, tool, args);
118 |   // Nothing is watched: a throwaway store gives the dormant answer.
119 |   if (!agent) return onMcp(createStore(), tool, args, push);
120 |   agent.lastActive = Date.now();
121 |   const text = await withRecords(agent, () => onMcp(agent.store, tool, args, tagged(push, agent)));
122 |   if (tool === "start_session") agent.task = agent.store.session?.task ?? agent.task;
123 |   return text;
124 | }
125 | 
126 | export function agentsInfo(squad: Squad): AgentInfo[] {
127 |   return [...squad.agents.values()].map((a) => ({ id: a.id, n: a.n, task: a.task, watching: isWatching(a), hold: a.store.hold }));
128 | }
