8 | export interface HookResult {
9 |   block?: string;
10 |   context?: string;
11 | }
12 | 
13 | export function onHook(store: StoreState, payload: HookPayload): HookResult {
14 |   if (payload.hook_event_name === "PreToolUse" && payload.tool_name === START_TOOL) {
15 |     bindSession(store, payload.session_id, payload.cwd);
16 |     return {};
17 |   }
18 | 
19 |   // Invariant 7: dormant for every task LazyCop was not invoked on
20 |   if (!isWatched(store, payload.session_id)) return {};
21 | 
22 |   // One record per tool call, once it has run
23 |   if (payload.hook_event_name === "PostToolUse") {
24 |     appendRecord({
25 |       kind: "event",
26 |       ts: new Date().toISOString(),
27 |       tool: payload.tool_name,
28 |       path: extractPath(payload.tool_input),
29 |       patch: extractPatch(payload),
30 |     });
31 |   }
32 | 
33 |   // Invariant 2: own MCP tools are never blocked
34 |   if (
35 |     payload.hook_event_name === "PreToolUse" &&
36 |     payload.tool_name.startsWith("mcp__lazycop__")
37 |   ) {
38 |     return {};
39 |   }
40 | 
41 |   if (payload.hook_event_name === "PreToolUse") {
42 |     if (store.hold) {
43 |       return {
44 |         block:
45 |           "LazyCop: the developer is reviewing an important decision. Call the lazycop check_in tool; it waits for the developer's answer. Do not end your turn.",
46 |       };
47 |     }
48 |     const msg = takePending(store, "block");
49 |     if (msg) {
50 |       noteDelivered(store, msg);
51 |       appendRecord({
52 |         kind: "message",
53 |         id: msg.id,
54 |         ...(msg.card ? { card: msg.card } : {}),
55 |         text: msg.text,
56 |         delivered_via: "hook",
57 |         ts: new Date().toISOString(),
58 |       });
59 |       return { block: `Message from the developer (via LazyCop): ${msg.text}` };
60 |     }
61 |     return {};
62 |   }
63 | 
64 |   if (
65 |     payload.hook_event_name === "PostToolUse" ||
66 |     payload.hook_event_name === "UserPromptSubmit"
67 |   ) {
68 |     const msg = takePending(store, "context");
69 |     if (msg) {
70 |       noteDelivered(store, msg);
71 |       appendRecord({
72 |         kind: "message",
73 |         id: msg.id,
74 |         ...(msg.card ? { card: msg.card } : {}),
75 |         text: msg.text,
76 |         delivered_via: "hook",
77 |         ts: new Date().toISOString(),
78 |       });
79 |       return { context: `Message from the developer (via LazyCop): ${msg.text}` };
80 |     }
81 |   }
82 | 
83 |   return {};
84 | }
85 | 
86 | function extractPath(input: unknown): string | undefined {
87 |   if (input && typeof input === "object") {
88 |     const p = (input as Record<string, unknown>)["path"];
89 |     if (typeof p === "string") return p;
90 |   }
91 |   return undefined;
92 | }
93 | 
94 | function extractPatch(payload: HookPayload): string | undefined {
95 |   if (payload.hook_event_name === "PostToolUse") {
96 |     const r = payload.tool_response;
97 |     if (typeof r === "string" && r.includes("@@")) return r;
98 |   }
99 |   return undefined;
