19 | export async function onMcp(
20 |   store: StoreState,
21 |   tool: string,
22 |   args: Record<string, unknown>,
23 |   push: Push,
24 | ): Promise<string> {
25 |   if (tool === "start_session") {
26 |     const { task, docs } = args as unknown as StartSessionInput;
27 |     startSession(store, String(task ?? ""));
28 |     push({ type: "session", on: true, task: store.session!.task, skills: definedSkills(store.session!.cwd) });
29 |     const loaded = loadNamedDocs(store, store.session!.cwd, docs, push);
30 |     const named = loaded.length ? ` LazyCop checks your assumptions against: ${loaded.join(", ")}.` : "";
31 |     return `LazyCop is watching this task. The developer follows along at ${pageUrl()}. Call declare_step before every file edit.${named}`;
